INSERT INTO `directions` VALUES (1,1,'1. 믹싱 글라스에 얼음을 넣는다.'),(2,1,'2. 보드카 40ml, 사과 리큐르 15ml, 쿠앵트로 15ml를 넣는다.'),(3,1,'3. 잘 저어 차가운 칵테일 글라스에 따른다.'),(4,1,'4. 사과 한 조각으로 장식한다.'),(5,2,'1. 슈터 글라스에 칼루아 20ml를 붓는다.'),(6,2,'2. 칼루아 위에 베일리스를 아주 조심스럽게 붓고 그랑 마니에르를 따른다.'),(7,2,'3. 불을 붙여 서브하고, 불이 붙은 상태에서 긴 빨대로 마신다.'),(8,3,'1. 셰이커에 각얼음을 채운다.'),(9,3,'2. 화이트 럼 45ml, 라임 주스 20ml, 그레나딘 시럽 10ml를 넣는다.'),(10,3,'3. 잘 흔들어 차게 식힌 칵테일 글라스에 따른다.'),(11,4,'1. 락글라스에 얼음을 채운다.'),(12,4,'2. 얼음 위에 보드카 50ml와 커피 리큐르 20ml를 붓는다.'),(13,4,'3. 부드럽게 저어준다.'),(14,5,'1. 하이볼 글라스에 얼음을 넣는다.'),(15,5,'2. 우스터소스 2-3대쉬, 타바스코 1대쉬, 소금, 후추를 추가한다.'),(16,5,'3. 얼음 위에 보드카 45ml, 토마토 주스 90ml, 레몬 주스 15ml를 붓는다.'),(17,5,'4. 부드럽게 저어주고 샐러리 줄기나 레몬 조각으로 장식한다.'),(18,6,'1. 슈터 글라스에 아마레토 20ml를 붓는다.'),(19,6,'2. 아마레토 위에 베일리스 20ml를 조심스럽게 붓는다.'),(20,6,'3. 휘핑크림을 얹는다.'),(21,7,'1. 셰이커에 얼음을 채운다.'),(22,7,'2. 화이트 럼 20ml, 보드카 20ml, 블루 큐라소 15ml를 넣는다.'),(23,7,'3. 파인애플 주스 90ml, 레몬 주스 15ml, 설탕 시럽 15ml를 넣는다.'),(24,7,'4. 원하는 만큼 흔들거나 저어 허리케인 글라스에 붓는다.'),(25,7,'5. 마라스키노 체리 또는 파인애플 조각으로 장식한다.'),(26,8,'1. 셰이커에 각얼음을 채운다.'),(27,8,'2. 보드카 50ml, 블루 큐라소 50ml, 라임 주스 50ml를 넣는다.'),(28,8,'3. 잘 흔들어서 샷을 만든다.'),(29,9,'1. 허리케인 글라스나 하이볼 글라스에 얼음을 넣는다.'),(30,9,'2. 보드카 30ml와 블루 큐라소 30ml를 넣는다.'),(31,9,'3. 레몬에이드 120ml를 올린다.'),(32,9,'4. 잘 저어준 후 레몬 조각으로 장식한다.'),(33,10,'1. 락 글라스나 하이볼 글라스에 얼음을 넣는다.'),(34,10,'2. 보드카 30ml, 블루 큐라소 15ml, 설탕 시럽 15ml를 붓는다.'),(35,10,'3. 자몽 주스 30ml를 추가합니다.'),(36,10,'4. 잘 저어준 후 오렌지 슬라이스로 장식한다.'),(37,11,'1. 락 글라스에 얼음을 채운다.'),(38,11,'2. 베일리스 45ml, 말리부 45ml, 위스키 45ml를 넣는다.'),(39,11,'3. 잘 저어준다.'),(40,12,'1. 맥주잔에 맥주 250ml를 붓는다.'),(41,12,'2. 위스키 한 잔을 맥주 속으로 떨어뜨려 맥주잔 바닥에 서있도록 한다.'),(42,12,'3. 칵테일을 한 번에 빠르게 마신다.'),(43,13,'1. 셰이커에 각얼음을 채운다.'),(44,13,'2. 브랜디 40ml, 우유 50ml, 설탕 시럽 10ml, 달걀노른자를 넣는다.'),(45,13,'3. 잘 흔든 후 얼음과 함께 하이볼 글라스에 따른다.'),(46,13,'4. 넛맥을 뿌린다.'),(47,14,'1. 셰이커에 얼음을 채운다.'),(48,14,'2. 진 60ml, 스위트 베르무트 15ml, 드라이 베르무트 10ml, 오렌지 주스 15ml를 넣는다.'),(49,14,'3. 잘 흔들어 칵테일 글라스에 따른다.'),(50,14,'4. 오렌지 껍질로 장식한다.'),(51,15,'1. 셰이커에 얼음을 채운다.'),(52,15,'2. 보드카 시트론 40ml, 쿠앵트로 15ml