/*!40000 ALTER TABLE `recipes` DISABLE KEYS */;
INSERT INTO `recipes` VALUES (1,NULL,'애플 마티니','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/01.애플마티니.jpg','애플티니(Appletini)라고도 불리며 보드카 대신 화이트럼을 사용하기도 합니다.','Apple Martini','35','2','2026-07-20 10:48:33'),(2,NULL,'B-52','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/02.B52.jpg','미국의 폭격기 B-52에서 이름을 따온 칵테일로 뚜렷한 3개의 층이 특징입니다. 얇게 도수 높은 술을 얹어서 불을 붙이면 플레이밍(Flaming) B-52라고 불립니다.','B-52','26','1','2026-07-20 10:48:34'),(3,NULL,'바카디 칵테일','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/03.바카디칵테일.jpg','주로 바카디 슈페리어로 만들고 식전주로 즐깁니다.','Bacardi Cocktail','33','1','2026-07-20 10:48:35'),(4,NULL,'블랙 러시안','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/04.블랙러시안.jpg','러시아의 전형적인 술인 보드카를 사용하고 커피 리큐르의 검은색을 사용하여 그 이름을 얻었습니다.','Black Russian','33','1','2026-07-20 10:48:37'),(5,NULL,'블러디 메리','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/05.블러디메리.jpg','피의 메리라는 이름은 영국의 메리 1세 여왕의 이름에서 비롯되었다고도 합니다. ','Bloody Mary','13','3','2026-07-20 10:48:38'),(6,NULL,'블로우 잡','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/06.blowjob.jpg','잔에 손을 대지 않고 입만 이용해서 원샷으로 먹는 달콤한 슈터 칵테일입니다.','Blow Job','15','1','2026-07-20 10:48:39'),(7,NULL,'블루 하와이','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/07.블루하와이.jpg','하와이 섬을 연상시키는 트로피컬 칵테일로 단맛에 비해 상쾌한 맛이 강하다. 비슷한 이름의 블루 하와이안 칵테일은 코코넛 크림이 사용되며 단맛이 더 풍부하다.','Blue Hawaii','11','3','2026-07-20 10:48:40'),(8,NULL,'블루 카미카제','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/08.블루카미카제.jpg','카미카제 칵테일의 샷 버전이며, 롱 드링크로도 만들 수 있습니다.','Blue Kamikaze','30','1','2026-07-20 10:48:42'),(9,NULL,'블루 라군','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/09.블루라군.jpg','파란색의 상큼한 칵테일로 푸른 호수라는 뜻입니다.','Blue Lagoon','10','2','2026-07-20 10:48:43'),(10,NULL,'블루 오션','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/10.블루오션.jpg','이국적인 스타일의 바다와 같은 아름다운 파란색의 달콤한 칵테일입니다.','Blue Ocean','17','3','2026-07-20 10:48:44'),(11,NULL,'BMW','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/11.BMW.jpg','베일리스(Baileys), 말리부(Malibu), 위스키(Whiskey)의 앞 글자를 따왔습니다.','BMW','26','1','2026-07-20 10:48:45'),(12,NULL,'보일러 메이커','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/12.boilermaker.jpg','위스키와 맥주를 함께 마시는 양맥 폭탄주를 말합니다. 맥주의 양은 취향에 따라 다를 수 있습니다.','Boilermaker','9','1','2026-07-20 10:48:47'),(13,NULL,'브랜디 에그노그','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/13.브랜디에그노그.jpg','원래 에그노그는 브랜디만이 아니라 각종 증류주나 와인 등도 베이스로 사용됩니다. 또한 알콜성분을 포함하지 않은 에그 노그도 있고 뜨겁게 핫 에그노그로도 마십니다.','Brandy Eggnog','16','2','2026-07-20 10:48:48'),(14,NULL,'브롱크스','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/14.브롱크스.jpg','향긋하고 약간 달콤한 과일향이 나는 인기 칵테일입니다.','Bronx','36','2','2026-07-20 10:48:49'),(15,NULL,'코스모폴리탄','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/15.코스모폴리탄.jpg','세련된 맛과 모던한 색감으로 뉴욕 여성들의 인기 칵테일로 알려져있는데 상큼하고 달콤한 맛에 비해 높은 도수의 칵테일입니다.','Cosmopolitan','26','2','2026-07-20 10:48:51'),(16,NULL,'쿠바 리브레','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/16.쿠바리브레.jpg','자유로운 쿠바라는 뜻으로 쿠바 독립전쟁 당시 지원하던 미군이 럼에 콜라를 넣어 마신것에서 유래되었습니다.','Cuba Libre','12','1','2026-07-20 10:48:52'),(17,NULL,'다이키리','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/17.다이키리.jpg','[IBA공식: THE UNFORGETTABLES] 쿠바의 광산 이름에서 따왔으며 광산기술자가 만들어 마셨다는 유래가 있습니다. 소설가 헤밍웨이가 즐겨마셨다고 합니다.','Daiquiri','34','2','2026-07-20 10:48:53'),(18,NULL,'더티 마티니','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/18.더티마티니1.jpg','올리브의 풍미가 강조되는 마티니의 변형 칵테일입니다.','Dirty Martini','32','2','2026-07-20 10:48:55'),(19,NULL,'에스프레소 마티니','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/19.에스프레소마티니1.jpg','약간의 카페인이 포함되는 마티니의 맛있는 변형 칵테일입니다.','Espresso Martini','22','2','2026-07-20 10:48:56'),(20,NULL,'깁슨','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/20.깁슨.jpg','진과 드라이 베르무트로 만들어 칵테일 어니언으로 장식됩니다.','Gibson','37','1','2026-07-20 10:48:57'),(21,NULL,'김렛','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/21.김렛.jpg','목공용 송곳이라는 이름은 송곳같이 날카롭게 찌르는 맛 때문에 붙여졌습니다. 진 대신에 보드카를 사용하는 보드카김렛도 인기가 있습니다.','Gimlet','32','2','2026-07-20 10:48:58'),(22,NULL,'진피즈','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/22.진피즈.jpg','[IBA공식 : THE UNFORGETTABLES] 라임 또는 레몬주스와 탄산수가 들어간 피즈 계열의 가장 인기 있는 칵테일. 달걀 흰자, 달걀 노른자, 스파클링 와인 등을 첨가하여 다양한 변형으로 응용됩니다.','Gin Fizz','13','2','2026-07-20 10:49:00'),(23,NULL,'진토닉','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/23.진토닉.jpg','간단하게 만들 수 있고 진과 토닉워너의 비율은 취향에 따라 다양할 수 있습니다.','Gin Tonic','13','1','2026-07-20 10:49:01'),(24,NULL,'갓파더','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/24.갓파더.jpg','스카치위스키와 아마레토가 잘 어우러진 풍부한 맛의 칵테일입니다.','Godfather','37','1','2026-07-20 10:49:02'),(25,NULL,'갓마더','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/25.갓마더.jpg','갓파더 칵테일과 짝을 이룬 칵테일로 위스키 대신 보드카가 사용됩니다.','Godmother','37','1','2026-07-20 10:49:03'),(26,NULL,'골드 러쉬','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/26.골드러쉬.jpg','설탕 시럽 대신 꿀을 첨가한 위스키 사워의 변형입니다.','Gold Rush','27','2','2026-07-20 10:49:05'),(27,NULL,'그래스호퍼','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/27.그래스호퍼.jpg','초록색 때문에 메뚜기라는 이름이 붙여졌다. 1950-60년대에 미국 남부 전역에서 인기를 얻었습니다.','Grasshopper','16','2','2026-07-20 10:49:06'),(28,NULL,'그린 멕시칸','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/28.greenmexican.jpg','우크라이나 바텐더가 녹색 바나나리큐르를 사용해서 만들었지만 일반적인 멜론리큐어로 대체되었습니다.','Green Mexican','24','2','2026-07-20 10:49:07'),(29,NULL,'하비 월뱅어','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/29.하비웰뱅어.jpg','캘리포니아 서퍼 하비가 즐겨마신 칵테일로 취해서 벽에 부딪히는 하비의 모습에서 이름을 따왔습니다.','Harvey Wallbanger','15','3','2026-07-20 10:49:08'),(30,NULL,'하이볼','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/30.하이볼.jpg','위스키로 간단하게 만드는 최고의 인기 칵테일입니다.','Highball','11','1','2026-07-20 10:49:10'),(31,NULL,'핫 토디','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/31.핫토디.jpg','보통 위스키에 꿀, 향신료를 넣어 만들고 뜨거운 물이나 따뜻한 차를 넣어 뜨겁게 제공합니다.','Hot Toddy','12','3','2026-07-20 10:49:11'),(32,NULL,'허리케인','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/32.허리케인.jpg','제2차 세계대전 시기에 만들어진 인기 트로피컬 칵테일로 허리케인 글라스에 서빙한것에서 이름지어졌습니다.','Hurricane','26','3','2026-07-20 10:49:12'),(33,NULL,'잭콕','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/33.잭콕.jpg','매우 간단하고 인기있는 칵테일 입니다. 여기에 싱글 몰트 스카치 위스키를 낭비하는 것은 권장되지 않습니다.','Jack Coke','10','1','2026-07-20 10:49:14'),(34,NULL,'예거밤','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/34.예거밤.jpg','예거마이스터와 에너지음료의 조합으로 핫식스를 사용해도 괜찮습니다.','Jager Bomb','10','1','2026-07-20 10:49:15'),(35,NULL,'젤리피쉬','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/35.jellyfish.jpg','물속을 떠다니는 해파리를 닮은 모습에서 이름붙여졌습니다.','Jellyfish','23','2','2026-07-20 10:49:16'),(36,NULL,'키르','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/36.키르.jpg','[IBA공식: CONTEMPORARY CLASSICS] 프랑스에서 식전주로 매우 인기가 있습니다. 샤도네이 화이트와인이 주로 사용됩니다.','Kir','11','1','2026-07-20 10:49:17'),(37,NULL,'레이디킬러','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/37.레이디킬러.jpg','1984년 챔피언십 우승을 차지한 달콤하고 아름다운 칵테일입니다.','Ladykiller','12','3','2026-07-20 10:49:19'),(38,NULL,'런던콜링','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/38.런던콜링.jpg',' 2002년에 런던에서 만들어진 칵테일로 잘 알려진 변형은 바나나콜링이 있습니다.','London Calling','29','3','2026-07-20 10:49:20'),(39,NULL,'롱아일랜드 아이스티','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/39.롱아일랜드아이스티.jpg','[IBA공식: CONTEMPORARY CLASSICS] 4가지 기주가 사용되며 아이스티와 색상이 비슷해서 이름 붙여졌습니다. 한국에서는 롱티라고 줄여부릅니다.','Long Island Iced Tea','29','3','2026-07-20 10:49:21'),(40,NULL,'마이타이','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/40.마이타이.jpg','[IBA공식: CONTEMPORARY CLASSICS] 타히티어로 최고라는 뜻이며 트로피컬 칵테일의 여왕이라 불립니다.','Mai Tai','30','3','2026-07-20 10:49:22'),(41,NULL,'맨하탄','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/41.manhattan.jpg','[IBA공식: THE UNFORGETTABLES] 칵테일의 여왕으로 불리는 인기 칵테일입니다.','Manhattan','34','2','2026-07-20 10:49:24'),(42,NULL,'마가리타','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/42.margarita.jpg','[IBA공식: TEMPORARYCLASSICS] 유리잔 테두리에 소금을 두르는것이 특징인 인기 칵테일입니다. 마르가리타라고도 불립니다.','Margarita','40','2','2026-07-20 10:49:25'),(43,NULL,'마티니','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/43.martini.jpg','칵테일의 왕으로 불리는 인기 칵테일이며, 다양한 마티니로 변형됩니다. 진과 베르무트 비율에 대해서는 많은 의견이 있습니다.','Martini','37','2','2026-07-20 10:49:26'),(44,NULL,'미도리 사워','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/44.midori_sour.jpg','멜론리큐르 미도리를 사용해서 만드는 사워 칵테일입니다. ','Midori Sour','14','1','2026-07-20 10:49:27'),(45,NULL,'모히또','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/45.mojito.jpg','[IBA공식: CONTEMPORARY CLASSICS] 쿠바에서 창조된 인기 칵테일로 소설가 헤밍웨이가 좋아한 칵테일로 유명합니다.','Mojito','19','3','2026-07-20 10:49:29'),(46,NULL,'모스코 뮬','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/46.moscow_mule.jpg','[IBA공식: CONTEMPORARY CLASSICS] 보통 구리로 만든 머그에 마시는 칵테일로 러시아인에게 구매했던 구리 머그에 새겨진 노새무늬 때문에 생긴 모스크바의 노새라는 별명이 이름이 되었습니다.','Moscow Mule','11','1','2026-07-20 10:49:30'),(47,NULL,'머드슬라이드','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/47.mudslide.jpg','블랙 러시안 칵테일의 변형으로 보통 컵 안쪽에 초코시럽으로 장식합니다.','Mudslide','24','1','2026-07-20 10:49:31'),(48,NULL,'네그로니','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/48.negroni.jpg','이탈리아 네그로니 백작이 즐겨마시던 식전주에서 이름을 따왔다는 유래가 있습니다.','Negroni','28','2','2026-07-20 10:49:33'),(49,NULL,'뉴욕 사워','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/49.new_york_sour.jpg','[IBA공식: NEW ERA DRINK] 위스키 사워 칵테일의 변형으로 서던 위스키 사워라고도 합니다.','New York Sour','27','3','2026-07-20 10:49:34'),(50,NULL,'올드 패션드','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/50.old_fashioned.jpg','비터드슬링이라 불리던 양주, 설탕, 비터의 단순한 조합이 다양하게 변형되었지만 변형 후의 칵테일과 구분하기위해 옛날방식을 의미하는 이름으로 부르게되었습니다.','Old Fashioned','33','3','2026-07-20 10:49:35'),(51,NULL,'오르가즘','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/51.orgasm.jpg','리큐르만으로 만드는 칵테일로 변형으로 보드카가 더해지면 스크리밍오르가즘(Screaming Orgasm) 칵테일이 됩니다.','Orgasm','22','1','2026-07-20 10:49:36'),(52,NULL,'페인킬러','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/52.페인킬러.jpg','1970년대에 창조된 퍼서스럼을 사용한 시그니처 칵테일로 다크럼으로 대체가능합니다.','Painkiller','10','3','2026-07-20 10:49:38'),(53,NULL,'피나 콜라다','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/53.pina_colada.jpg','[IBA공식: CONTEMPORARY CLASSICS] 스페인어로 채에 거른 파인애플이라는 뜻으로 인기있는 트로피컬 칵테일입니다.','Pina Colada','15','3','2026-07-20 10:49:39'),(54,NULL,'라모스 피즈','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/54.ramos_fizz.jpg','[IBA공식: UNFORGETTABLES] 바텐더 헨리 찰스 칼 라모스에 의해 만들어진 장시간의 셰이킹이 필요한 칵테일입니다.','Ramos Fizz','11','3','2026-07-20 10:49:40'),(55,NULL,'러스티 네일','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/55.rusty_nail.jpg','[IBA공식: UNFORGETTABLES] 식후에 마시는 칵테일로 온더락 또는 니트로 제공 될 수 있습니다.','Rusty Nail','40','1','2026-07-20 10:49:41'),(56,NULL,'샹그리아','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/56.sangria.jpg','와인에 여러가지 과일을 넣어 마시는 스페인의 대중적인 술입니다. 피를 의미하는 스페인어 sangre에서 유래되었습니다.','Sangria','13','3','2026-07-20 10:49:43'),(57,NULL,'스크류드라이버','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/57.screwdriver2.jpg','이란에서 일하던 미국 석유 엔지니어가 몰래 보드카를 오렌지 주스에 넣고 드라이버로 섞어먹었다는 유래가 있습니다.','Screwdriver','13','1','2026-07-20 10:49:44'),(58,NULL,'시브리즈','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/58.sea_breeze.jpg','[IBA공식: CONTEMPORARY CLASSICS] 바닷바람이라는 뜻으로 주스가 많이 들어가는 인기 칵테일입니다.','Sea Breeze','8','2','2026-07-20 10:49:45'),(59,NULL,'섹스온더비치','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/59.sex_on_the_beach.jpg','[IBA공식: CONTEMPORARY CLASSICS] 인기있는 칵테일로 다양한 변형이 있습니다. 모던 섹스 온 더 비치에는 오렌지 주스 대신 파인애플 주스가 들어갑니다.','Sex on the beach','14','2','2026-07-20 10:49:47'),(60,NULL,'사이드 카','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/60.sidecar.jpg','사이드카 오토바이에서 이름을 따온 칵테일로 제1차 세계 대전 중에 파리의 비스트로에서 만들어졌다고 합니다.','Sidecar','40','2','2026-07-20 10:49:48'),(61,NULL,'실버 불렛','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/61.silver_bullet.jpg','강한 스카치 위스키 향과 진 때문에 호불호가 있습니다. 진과 스카치 위스키의 비율은 매우 다양할 수 있으며 슈터로도 만들 수 있습니다.','Silver Bullet','40','1','2026-07-20 10:49:49'),(62,NULL,'싱가포르 슬링','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/62.singapore_sling.jpg','[IBA공식: CONTEMPORARY CLASSICS] 싱가포르 래플스 호텔의 롱바에서 바텐더가 당시 공공장소에서 술을 마실수 없던 여성들을 위해 과일주스처럼 보이는 칵테일을 만들었다고 합니다.','Singapore Sling','11','2','2026-07-20 10:49:51'),(63,NULL,'데킬라 선라이즈','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/63.tequila_sunrise.jpg','[IBA공식: CONTEMPORARY CLASSICS] 일출을 닮았다고해서 붙여진 이름으로 그라데이션으로 해 뜰 때의 붉은 하늘을 연상시킵니다.','Tequila Sunrise','12','2','2026-07-20 10:49:52'),(64,NULL,'보드카 마티니','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/64.vodka_martini.jpg','마티니 칵테일의 보드카 기반 변형입니다. 보드카와 베르무트의 비율은 취향에 따라 달라질 수 있습니다.','Vodka Martini','35','2','2026-07-20 10:49:53'),(65,NULL,'화이트 러시안','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/65.white_russian.jpg','크림을 첨가한 블랙 러시안 칵테일의 변형. 보드카가 주재료이기 때문에 러시안이라는 이름이 붙었습니다.','White Russian','23','1','2026-07-20 10:49:54'),(66,NULL,'꿀주','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/66.Honey cocktail.jpg','가수 다비치의 강민경이 쇼프로에서 소개하면서 유명해진 소맥 중 하나. 맥주가 섞여 색이 변하는 순간 한번에 마셔야 진정한 꿀맛을 느낄 수 있습니다.','Honey Cocktail','16','1','2026-07-20 10:49:55'),(67,NULL,'에너자이저주','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/67.Energyju.jpg','편의점에서 쉽게 재료를 구해서 만들 수 있는 인기있는 소주 칵테일입니다.','Energyju','6','1','2026-07-20 10:49:57'),(68,NULL,'고진감래주','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/68.No pain, No gain.jpg','고생이 다하면 즐거움이 찾아온다는 한자성어 고진감래의 의미를 가진 폭탄주. 마시면 소주의 쓴 맛 뒤에 달달한 콜라를 먹게되므로 고진감래라고 이름 붙여졌습니다.','No pain, No gain','6','2','2026-07-20 10:49:58'),(69,NULL,'한라토닉','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/69.Halla Tonic.jpg','소주로 쉽게 만들 수 있는 하이볼. 제주도의 한라산 소주를 사용하면 더 맛이 좋습니다. 화요 25도 짜리로 만드는 화요토닉도 있습니다.','Halla Tonic','6','2','2026-07-20 10:49:59'),(70,NULL,'로이 로저스','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/70.Roy Rogers.jpg','미국의 배우이자 가수인 로이 로저스의 이름을 딴 상쾌한 무알콜 칵테일입니다.','Roy Rogers','0','1','2026-07-20 10:50:00'),(71,NULL,'셜리 템플','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/71.Shirley_temple.jpg','미국의 아역배우 셜리 템플을 위해 만들어진 심플하고 대중적인 무알콜 칵테일입니다.','Shirley Temple','0','2','2026-07-20 10:50:01'),(72,NULL,'버진 피나 콜라다','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/72.Virgin Colada.jpg','피나 콜라다의 무알콜 버전입니다.','Virgin Pina Colada','0','3','2026-07-20 10:50:03'),(73,NULL,'빨간칵테일','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/6f4a369a-11c0-47d8-b181-2a099a22793fb76f44b6b4e35ff1e9668e900.skycranberry.jpg','맛있는 빨간색 칵테일 컬렉션입니다~~\r\n겨울에는 따뜻한 느낌을 주는 빨간 칵테일 어떤가요?','Red Cocktail','0','1','2026-07-20 10:53:11'),(74,NULL,'민트 줄렙','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/bfaf0dbd-1e7b-47b9-9b3c-59d921264cb6scaled_image_picker1244164044065037431.png','[IBA공식: CONTEMPORARY CLASSICS] 미국 남부지방의 음료가 유럽에 소개되며 칵테일로 정착되었다. 이름에서 알 수 있듯 민트는 가니쉬가 아닌 필수재료이다','Mint Julep','45','2','2026-07-20 10:53:33'),(75,NULL,'화이트 레이디','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/1324abe5-2766-49b6-875d-4ddfe433febfea053c866a14f685269d7450d.png','[IBA공식: THE UNFORGETTABLES] 화이트 레이디(White Lady) 칵테일은 20세기 초에 등장한 클래식 칵테일 중 하나로 그 부드럽고 크리미한 질감 때문에 많은 사람들이 좋아하는 칵테일 중 하나입니다.','White Lady','30','1','2026-07-20 10:54:58'),(76,NULL,'불바디에','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/3a507418-d3ef-4d04-82f1-1eaba5362f8bea053c866a14f685269d74515.png','[IBA공식: THE UNFORGETTABLES] 프랑스의 문화잡지인 Boulevardier의 이름을 따와서 만든 칵테일.\r\n해당 잡지는 본래 파리에서 인기 있던 장소와 문화, 칵테일 등에 대한 정보를 제공하는 잡지였','Boulevardier','32','2','2026-07-20 10:55:09'),(77,NULL,'알렉산더','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/65de4cf2-7625-45f2-b0fb-22904a314a62dddd77e0d32ab36380220ce00.jpeg','[IBA공식:THE UNFORGETTABLES] \r\n조주기능사 시험에서는 \'브랜디 알렉산더\'라 표기하는 칵테일로 브랜디 베이스 칵테일입니다.','Alexander','21','1','2026-07-20 10:56:12'),(78,NULL,'아메리카노','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/9d7cfac2-3c60-4e30-8302-2e7ce8a7f561dddd77e0d32ab36380220ce01.jpeg','[IBA공식:THE UNFORGETTABLES] 아메리카노의 역사는 1800년대 후반 밀라노의 Gaspare Campari 바에서 시작되었다고 합니다. 영화 007의 제임스 본드를 비롯해 많은 영화를 통해 널리 알려지게 되었습니다.','Americano','14','2','2026-07-20 10:56:13'),(79,NULL,'엔젤 페이스','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/9edec4d0-ce3f-4e80-aa8d-199e5fd2db95dddd77e0d32ab36380220ce02.webp','[IBA공식:THE UNFORGETTABLES] 이 칵테일은 고전적인 칵테일 중 하나로 많은 사랑을 받고 있습니다. 엔젤 페이스는 그의 고유한 맛과 고급스러운 조합으로 많은 이들에게 선호되는 칵테일 중 하나로 손꼽힙니다','Angel Face','35','2','2026-07-20 10:56:14'),(80,NULL,'에비에이션','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/4cdf4ede-c445-450e-90b5-863bd60e1fd3dddd77e0d32ab36380220ce03.webp','[IBA공식:THE UNFORGETTABLES] 에비에이션 칵테일은 1916년에 호텔 리델(Ritz Hotel)의 바텐더인 호가트 코넬리(Hugo Ensslin)가 처음으로 만들었습니다. 이 칵테일은 항공에 영감을 받아 이름이 지어졌는데, 보라색 빛깔이 비행기 하늘을 연상시키기 때문입니다','Aviation','27','2','2026-07-20 10:56:15'),(81,NULL,'비트윈 더 시트','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/47ed482a-b73e-4f06-bd1d-026778972bf1dddd77e0d32ab36380220ce04.webp','[IBA공식:THE UNFORGETTABLES] 비트윈 더 시트 칵테일은 이름처럼 자기전에 마시기 적합한 음료로 알려져 있습니다. 단맛과 쓴맛의 중간으로 균형 잡힌 맛을 가지고 있어 거부감 없이 즐길 수 있습니다','Between the Sheets','27','2','2026-07-20 10:56:18'),(82,NULL,'브랜디 크러스타','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/8ac5c124-9032-4373-9df3-48bb82460895dddd77e0d32ab36380220ce05.webp','[IBA공식: THE UNFORGETTABLES] 브랜디 크러스타(Brandy Crusta)는 장식용 레몬 껍질을 장식으로 사용한 최초의 칵테일 중 하나로, 미래 믹스솔로지의 트렌드를 설정했다고 평가받는 칵테일입니다.','Brandy Crusta','31','3','2026-07-20 10:56:19'),(83,NULL,'카지노','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/fcd5a391-261f-457e-95cc-160a08b6fdc4dddd77e0d32ab36380220ce06.webp','[IBA공식: THE UNFORGETTABLES] 카지노 칵테일은 1930년대 미국 라스베이거스의 카지노 호텔에서 일을하던 바텐더가 만들었다고 합니다. 그 당시 호텔의 이름이 그대로 칵테일의 이름으로 사용되었습니다.','Casino','32','2','2026-07-20 10:56:20'),(84,NULL,'클로버 클럽','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/f3b082a1-81f7-41e0-bf87-f19766e8f255scaled_1000011970.webp','[IBA공식: THE UNFORGETTABLES] 클로버 클럽 칵테일은 1910년대 뉴욕의 클럽인 \"클로버 클럽\"에서 탄생했습니다. 이 칵테일은 미국에서 금주령이 시행되기 전에 인기 있던 음료 중 하나였습니다.','Clover Club','24','2','2026-07-20 10:56:21'),(85,NULL,'드라이 마티니','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/b3de91cc-1c40-4a90-b4ac-8a63c274d45edddd77e0d32ab36380220ce08.webp','[IBA공식: THE UNFORGETTABLES] 마티니라는 이름은 이탈리아 베르무트 회사 Martini & Rossi에서 유래되었다고 합니다. 이 회사는 1890년대에 베르무트를 생산하면서 자신들의 제품을 홍보하기 위해 마티니 칵테일 레시피를 사용했습니다.','Dry Martini','37','1','2026-07-20 10:56:23'),(86,NULL,'행키팽키','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/a762ff2c-428c-4967-8eb2-51b67f01f897dddd77e0d32ab36380220ce09.webp','[IBA공식: THE UNFORGETTABLES] Hanky Panky 칵테일은 1903년에 런던의 Savoy Hotel 바텐더인 Ada Coleman이 처음 만들었다고 알려져 있습니다. 이 칵테일은 감미로운 맛과 향을 가지고 있으며, 계속해서 인기를 끌고 있습니다','Hanky Panky','29','1','2026-07-20 10:56:24'),(87,NULL,'존 콜린스','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/854d0f98-34a1-4976-8005-89f443607ea6scaled_1000012143.jpg','[IBA공식: THE UNFORGETTABLES] 존 콜린스 칵테일의 기원은 19세기 초 영국 런던으로 거슬러 올라갑니다. 이 칵테일은 런던의 인기 호텔이자 커피하우스인 Limmer\'s Old House에서 일했던 John Collins라는 바텐더의 작품입니다.','John Collins','12','2','2026-07-20 10:56:25'),(88,NULL,'마르티네즈','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/1847774c-f729-4641-bda0-32fe64631b5debf02c8cf2a2036911058e301.jpg','[IBA공식: THE UNFORGETTABLES] 마르티네즈 칵테일은 정확한 유래가 있지는 않지만 19세기 중반 캘리포니아주 마르티네즈에서 유래된 것으로 추정됩니다. 마을을 지나가는 여행자를 위한 특별한 칵테일로 제작 되었습니다.','Martinez','29','2','2026-07-20 10:56:26'),(89,NULL,'메리 픽포드','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/ca47c6a4-9db8-49df-8e9c-a05cbb12b37aebf02c8cf2a2036911058e302.jpg','[IBA공식: THE UNFORGETTABLES] 1920년대 금주법 기간 동안 할리우드에서 유명한 배우였던 메리 픽포드(Mary Pickford)의 방문에서 영감을 받아 하바나의 Hotel Nacional de Cuba에서 칵테일이 탄생했습니다.','Mary Pickford','20','2','2026-07-20 10:56:32'),(90,NULL,'몽키 글랜드','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/35e1e49d-6d76-47c0-bc5b-a69849c828b2ebf02c8cf2a2036911058e303.jpg','[IBA공식: THE UNFORGETTABLES] 1920년대 파리 Harry\'s New York Bar의 스코틀랜드계 미국인 바텐더인 Harry MacElhone이 발명한 Monkey Gland 칵테일은 금지 시대에 인기를 얻었습니다.','Monkey Gland','20','1','2026-07-20 10:56:33'),(91,NULL,'파라다이스','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/d72cf346-e35a-40e2-8c57-bbce8dae8602ebf02c8cf2a2036911058e304.jpeg','[IBA공식: THE UNFORGETTABLES] 생생한 색상과 열대 성분이 어우러진 파라다이스 칵테일은 햇빛이 비치는 무성한 천국의 이미지를 불러일으키며 이국적인 맛을 원하는 사람들에게 사랑받을 수 있는 칵테일 입니다.','Paradise','26','1','2026-07-20 10:56:36'),(92,NULL,'플랜터스 펀치','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/f72c45de-cde6-4754-a237-d8a17d0edc3aebf02c8cf2a2036911058e305.jpg','[IBA공식: THE UNFORGETTABLES] 플랜터스 펀치는 19세기 후반과 20세기 초반에 광범위한 인기를 얻었으며 전 세계 바와 칵테일 라운지의 필수 메뉴가 되었습니다. 카리브해의 환대와 휴식의 상징으로서의 명성은 오늘날까지도 지속되고 있습니다.','Planter’s Punch','20','1','2026-07-20 10:56:37'),(93,NULL,'포르토 플립','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/233171d9-1e43-42e4-9a98-10a8623cda3aebf02c8cf2a2036911058e306.webp','[IBA공식:  THE UNFORGETTABLES] 포르토 플립의 \"포르투\"라는 이름은 포르투갈의 달콤하고 강화된 와인인 포트 와인을 사용하는 데서 유래되었습니다. 원래는 단순히 \"플립\"으로 알려졌습니다.','Porto Flip','18','1','2026-07-20 10:56:38'),(94,NULL,'사제락','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/836090c4-2f33-4d20-aba1-949aa262066febf02c8cf2a2036911058e307.jpg','[IBA공식: THE UNFORGETTABLES] 기원은 1830년대로 거슬러 올라간다는 소문이 있어 \"최초의 칵테일\"이라는 별명을 가지고 있는 칵테일 입니다.','Sazerac','35','2','2026-07-20 10:56:39'),(95,NULL,'스팅어','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/5bcdef2d-4412-46f9-aebc-301d4aedbf36scaled_1385.jpg','[IBA공식: THE UNFORGETTABLES] 원래 달콤한 식후 음료로 제공되었던 스팅어 칵테일은 시간이 지남에 따라 다양한 변형이 등장했습니다. 단순함과 상쾌한 민트 향이 매력적이며, 시대를 초월한 클래식으로 자리매김하고 있습니다.','Stinger','35','2','2026-07-20 10:56:44'),(96,NULL,'턱시도','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/b3ef0729-a6d9-406b-9846-9c02fda15835ebf02c8cf2a2036911058e30b.jpg','[IBA공식: THE UNFORGETTABLES] 칵테일은 일반적으로 드라이 진, 드라이 셰리, 오렌지 비터로 구성되어 우아함과 세련미를 뽐냅니다.','Tuxedo','29','2','2026-07-20 10:56:45'),(97,NULL,'뷰 카레','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/e3e24fbe-197a-42b4-b67d-1ec0b85c42f0ebf02c8cf2a2036911058e30c.jpg','[IBA공식: THE UNFORGETTABLES] \"Vieux Carré\"라는 이름은 \"오래된 광장\"으로 번역됩니다. 이 음료는 다양한 재료를 혼합하여 뉴올리언스의 정신을 구현하고 도시의 활기찬 문화와 유산을 맛볼 수 있습니다.','Vieux Carrè','32','2','2026-07-20 10:56:46'),(98,NULL,'위스키 사워','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/bbe0c7e6-6746-4421-b5c0-8031dfa7dac2scaled_1386.webp','[IBA공식: THE UNFORGETTABLES] 위스키 사워의 기원은 19세기 중반으로 거슬러 올라갑니다. 정확한 기원은 다소 미스터리이나, 한 이야기에 따르면 장거리 항해 중 괴혈병을 예방하기 위해 감귤류와 증류주를 혼합하는 선원들의 관행에서 발전했다고 합니다.','Whiskey Sour','18','2','2026-07-20 10:56:48'),(99,NULL,'프렌치 75','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/fe37e8da-cd04-4749-81d5-6591573f6bb9a6cc69039a429269edc9ce604.jpg','[IBA공식: CONTEMPORARY CLASSICS] 프렌치 75는 제1차 세계대전 당시 프랑스군이 사용했던 75mm 포병 무기에서 유래되었습니다. 이 포는 강력한 파괴력 덕분에 유명했으며, 이 칵테일 역시 강력한 맛과 영향을 준다고 해서 이 무기의 이름을 따왔습니다.','French 75','15','2','2026-07-20 10:57:28'),(100,NULL,'골든 드림','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/3fb10476-0434-48cd-b910-c440fe1352b4a6cc69039a429269edc9ce605.jpeg','[IBA공식: CONTEMPORARY CLASSICS] 골든 드림 칵테일은 밝은 주황색의 칵테일로, 그 맛과 색상에서 따뜻하고 달콤한 느낌을 줍니다.','Golden Dream','14','1','2026-07-20 10:57:30'),(101,NULL,'헤밍웨이 스페셜','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/8e8830f9-c5fd-4427-b453-95dba5370785a6cc69039a429269edc9ce60b.jpg','[IBA공식: CONTEMPORARY CLASSICS] 강한 맛을 가진 칵테일을 좋아했던 헤밍웨이는 바에 들어가서 다이키리를 시음해보았는데, 맛은 좋았지만 너무 달다고 생각했습니다. 그래서 그는 설탕 없이 럼을 두 배로 넣어달라고 요청했고, 이렇게 만들어진 것이 우리가 지금 알고 있는 밍웨이 스페셜 입니다.','Hemingway Special','22','2','2026-07-20 10:57:35'),(102,NULL,'홀시스 넥','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/abb18a90-3e4d-47b5-b820-5d059852f2e7a6cc69039a429269edc9ce60c.jpg','[IBA공식: CONTEMPORARY CLASSICS] 이 칵테일의 독특한 이름은 음료에 사용되는 긴 레몬 껍질 장식에서 유래했습니다. 레몬 껍질을 나선형으로 길게 깎아 유리잔에 걸쳐 놓으면, 그 모양이 마치 말의 목처럼 보인다고 해서 \"Horse\'s Neck\"이라는 이름이 붙었습니다.','Horse’s Neck','8','2','2026-07-20 10:57:37'),(103,NULL,'아이리쉬 커피','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/374df35c-8885-4e89-a76a-8aad22303472a6cc69039a429269edc9ce60d.jpeg','[IBA공식: CONTEMPORARY CLASSICS] 커피와 아이리쉬 위스키를 섞어 만든 음료로, 따뜻하고 풍부한 맛이 특징입니다.','Irish Coffee','9','2','2026-07-20 10:57:38'),(104,NULL,'미모사','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/5894e7e4-7a18-438b-87b1-8078b8802649a6cc69039a429269edc9ce60e.jpg','[IBA공식: CONTEMPORARY CLASSICS] 미모사 칵테일은 샴페인과 오렌지 주스를 1:1 비율로 혼합하여 만든 상큼한 매력이 돋보이는 음료입니다. 대표적인 브런치 칵테일로 잘 알려져 있습니다.','Mimosa','6','1','2026-07-20 10:57:39'),(105,NULL,'피스코 사워','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/9107ee52-0c05-44a3-a9dd-a6b65ade22d1a6cc69039a429269edc9ce60f.jpeg','[IBA공식: CONTEMPORARY CLASSICS] 피스코사워(Pisco Sour)는 페루와 칠레의 전통 칵테일로, 두 나라 모두 이 칵테일을 자국의 대표 음료로 자부합니다. 피스코사워는 피스코(Pisco)라는 증류주를 기본으로 하고, 라임 주스, 단순 시럽, 얼음, 계란 흰자, 그리고 약간의 비터스로 만든 상쾌하고 달콤한 칵테일입니다.','Pisco Sour','21','2','2026-07-20 10:57:41'),(106,NULL,'베스퍼','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/58a1518f-ed31-4370-83a7-7447c1dd7538a6cc69039a429269edc9ce610.jpg','[IBA공식: CONTEMPORARY CLASSICS] 베스퍼 칵테일(Vesper Martini)은 제임스 본드 시리즈에서 유명해진 칵테일로, 제임스 본드가 이 칵테일을 주문하면서, 그 이름을 베스퍼 린드(Vesper Lynd)라는 캐릭터의 이름을 따서 붙였습니다.','Vesper','37','2','2026-07-20 10:57:42'),(107,NULL,'좀비','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/41a6186f-8681-491c-a3a8-2bfaf1af19cba6cc69039a429269edc9ce611.webp','[IBA공식: CONTEMPORARY CLASSICS] 좀비칵테일을 창작한 돈비치는 정확한 레시피를 비밀로 유지했습니다. 이로 인해 좀비 칵테일은 다양한 변형 레시피가 존재하게 되었습니다.','Zombie','29','2','2026-07-20 10:57:43'),(108,NULL,'바라쿠다','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/03310ddd-47e6-454d-9911-f7e4c5304d70a6cc69039a429269edc9ce612.jpeg','[IBA공식: NEW ERA DRINKS] 바라쿠다 칵테일의 이름은 열대 바다에서 발견되는 공격적이고 빠른 물고기인 바라쿠다에서 따왔습니다. 이 물고기는 민첩하고 날카로운 이빨을 가지고 있어 강한 인상을 주며, 칵테일도 이런 이미지를 반영하여 강렬한 맛과 색을 특징으로 합니다.','Barracuda','17','3','2026-07-20 10:57:45'),(109,NULL,'비스 니즈','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/f60011d0-0ffa-4100-acb5-5fd25cf03b4aa6cc69039a429269edc9ce613.jpg','[IBA공식: NEW ERA DRINKS] \"Bee’s Knees\"라는 표현은 1920년대에 \"최고\", \"멋진 것\"을 의미하는 속어로 사용되었습니다. 이 칵테일의 이름은 바로 이 표현에서 유래되었으며, 칵테일이 정말 멋지고 훌륭하다는 뜻을 담고 있습니다.','Bee’s Knees','21','3','2026-07-20 10:57:47'),(110,NULL,'브램블','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/df5d7f67-f7d8-40d7-b697-1da1e96d8bb8a6cc69039a429269edc9ce614.jpeg','[IBA공식: NEW ERA DRINKS] 브램블 칵테일은 비교적 최근에 탄생한 클래식 칵테일로, 1984년에 런던의 유명한 바텐더인 딕 브래드셀에 의해 만들어졌습니다.','Bramble','22','3','2026-07-20 10:57:49'),(111,NULL,'칸찬차라','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/b99d8737-0a5c-448b-a627-f9fc9cd7b763a6cc69039a429269edc9ce615.jpg','[IBA공식: NEW ERA DRINKS] 칸찬차라 칵테일(Canchánchara)은 쿠바의 역사와 깊이 연관된 전통 칵테일로, 쿠바 독립 전쟁 당시 병사들에 의해 만들어진 것으로 알려져 있습니다. 이 칵테일의 기원은 19세기 후반으로 거슬러 올라가며, 쿠바가 스페인으로부터 독립하기 위해 싸우던 시기에 창조된 음료입니다.','Canchanchara','12','2','2026-07-20 10:57:50'),(112,NULL,'페르난디토','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/6b0a820a-e5b7-4a03-bafc-8a6ec519c799a6cc69039a429269edc9ce616.jpg','[IBA공식: NEW ERA DRINKS] 아르헨티나의 전설적인 축구 선수 디에고 마라도나는 페르난디토 칵테일의 열렬한 팬이었습니다. 그는 인터뷰에서 자주 이 음료를 즐긴다고 언급했으며, 이는 페르난디토의 인기를 더욱 높이는 계기가 되었습니다.','Fernandito','10','1','2026-07-20 10:57:52'),(113,NULL,'프렌치 마티니','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/9d0d6bc2-59da-4df8-b8ee-67deb26c9776a6cc69039a429269edc9ce617.jpg','[IBA공식: NEW ERA DRINKS] 프렌치 마티니는 1980년대 후반에 뉴욕 시에서 탄생한 칵테일로, 그 이름과는 달리 프랑스에서 유래하지 않았습니다.','French Martini','27','2','2026-07-20 10:57:53'),(114,NULL,'일레갈','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/6b4be670-8103-4471-80cc-4b5a194cd590a6cc69039a429269edc9ce618.jpg','[IBA공식: NEW ERA DRINKS] 일레갈 칵테일은 미국 금주법 시대에(1920-1933) 불법적으로 만들어진 칵테일이란 뜻에서 이름 붙여졌습니다.','illegal','23','2','2026-07-20 10:57:54'),(115,NULL,'네이키드 앤 패이머스','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/0f85813e-516c-4cb3-b387-91d9163552d5a6cc69039a429269edc9ce619.jpg','[IBA공식: NEW ERA DRINKS] 네이키드 앤 패이머스 칵테일은 비교적 최근에 탄생한 칵테일로, 정체성 자체가 꽤 실험적고 \"평범하지 않음\"을 강조하고자 하는 의도가 담겨 있습니다.','Naked and Famous','22','2','2026-07-20 10:57:56'),(116,NULL,'올드 쿠반','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/78a91e6e-653f-43df-9e6c-b71caabf0f37a6cc69039a429269edc9ce61a.jpg','[IBA공식: NEW ERA DRINKS] 이 칵테일은 이름에서 알 수 있듯이 쿠바의 전통과 역사를 염두에 두고 만들어졌습니다. 럼주는 쿠바의 상징적인 술이며, 모히토의 민트와 럼에 프렌치 75의 샴페인을 더해, 전통과 현대가 조화롭게 어우러진 맛을 완성한 것이 특징입니다.','Old Cuban','15','2','2026-07-20 10:57:57'),(117,NULL,'페이퍼 플레인','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/83c106d7-19dc-49f2-8a14-455768fb3988a6cc69039a429269edc9ce61b.jpg','[IBA공식: NEW ERA DRINKS] 이 칵테일의 이름은 영국의 힙합 아티스트 M.I.A.의 히트곡 \"Paper Planes\"에서 영감을 받아 지어졌습니다.','Paper Plane','22','2','2026-07-20 10:57:58'),(118,NULL,'페니실린','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/9f49b126-a746-44b2-8ac9-c4dd61b8e850a6cc69039a429269edc9ce651.jpg','[IBA공식: NEW ERA DRINKS] 페니실린이라는 이름은 최초의 항생제인 페니실린에서 따온 것입니다. 스카치 위스키의 강한 맛을 부드럽게 만들고, 감기나 목에 좋다고 알려진 재료들을 사용하여 만든 칵테일 입니다.','Penicillin','0','3','2026-07-20 10:58:04'),(119,NULL,'스파이시 피프티','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/6905db0b-c4e4-4498-9c14-bcefa84e87b1a6cc69039a429269edc9ce652.jpg','[IBA공식: NEW ERA DRINKS] 스파이시 피프티는 특유의 매콤함과 달콤함이 균형을 이루는 맛으로 인해 빠르게 인기를 끌었습니다. 특히 더운 여름날이나 특별한 이벤트에서 즐기기 좋은 칵테일로 사랑받고 있습니다.','Spicy Fifty','24','2','2026-07-20 10:58:05'),(120,NULL,'스프리츠','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/d3838cc4-5a53-452b-9a9a-964fc12207f9a6cc69039a429269edc9ce653.jpg','[IBA공식: NEW ERA DRINKS] \"스프리츠(Spritz)\"는 독일어로 \"튀기다\" 또는 \"스프레이하다\"라는 의미로, 와인에 물을 타는 행위를 가리키는 용어 입니다.','Spritz','10','1','2026-07-20 10:58:06'),(121,NULL,'서퍼링 바스타드','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/e948cbe0-ac1b-4dae-9cfd-1e304692970aa6cc69039a429269edc9ce659.jpg','[IBA공식: NEW ERA DRINKS] 제2차 세계대전 당시 전쟁으로 피로에 지친 손님들이 마시고 나면 \"그 지독한 고통을 날려 버릴 수 있다\"는 의미에서 이름붙여진 칵테일','Suffering Bastard','23','3','2026-07-20 10:58:07'),(122,NULL,'티퍼레리','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/f29bce00-1e5d-487b-bf7b-463cf3e8bed7a6cc69039a429269edc9ce65b.jpg','[IBA공식: NEW ERA DRINKS] 이름은 아일랜드의 한 지역인 티퍼레리(Tipperary)에서 유래한 것으로, 아일랜드 위스키를 기반으로 만들어집니다.','Tipperary','36','2','2026-07-20 10:58:09'),(123,NULL,'토미스 마가리타','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/5349ec75-921b-4645-8485-09bd018bab0da6cc69039a429269edc9ce65c.jpg','[IBA공식: NEW ERA DRINKS] 고전적인 마가리타에서 약간 변형된 레시피로, 재료가 더 단순해졌습니다. 테킬라, 라임 주스, 그리고 아가베 시럽만을 사용하여 만들어지며, 그 단순함 덕분에 테킬라의 품질이 중요하게 작용합니다.','Tommy’s Margarita','20','2','2026-07-20 10:58:10'),(124,NULL,'트리니다드 사워','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/52d2906b-a851-4b9c-9fdd-2b42b291a4dea6cc69039a429269edc9ce669.jpg','[IBA공식: NEW ERA DRINKS] 트리니다드 사워의 독특한 점은 일반적인 칵테일에서는 소량만 들어가는 앙고스투라 비터스를 주요 성분으로 사용한다는 것입니다.','Trinidad Sour','23','1','2026-07-20 10:58:11'),(125,NULL,'VE.N.TO','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/b79838f5-bc46-4655-a052-d174ff778e89a6cc69039a429269edc9ce66a.N.TO.jpg','[IBA공식: NEW ERA DRINKS] VE.N.TO는 이탈리아의 베네치아를 중심으로 만들어진 칵테일로, 이름 자체가 이탈리아어로 \"바람\"을 의미하는 vento에서 유래했습니다.','VE.N.TO','0','2','2026-07-20 10:58:13'),(126,NULL,'옐로 버드','https://masileng-bucket.s3.ap-northeast-2.amazonaws.com/TB_COCK_MASTER/bc73b73e-95c8-4c49-97dd-098bcb024c66a6cc69039a429269edc9ce66b.jpg','[IBA공식: NEW ERA DRINKS] 옐로 버드 칵테일은 카리브해의 따뜻한 기후와 열대적인 분위기를 담은 클래식한 칵테일입니다. 이름의 유래는 자메이카의 민속 노래 \"Yellow Bird\"에서 비롯되었다고 알려져 있습니다.','Yellow bird','26','2','2026-07-20 10:58:14');
